"kind": "propose",
"summary": "The application's liveness probe failed during startup due to a timeout that was too short, causing premature termination. Adjusting the probe's timeout and initial delay will allow the app to respond before being killed.",
"hypotheses": [
  {
    "root_cause_class": "probe_too_strict_for_startup",
    "summary": "The liveness probe failed during startup, killing the container before it could respond.",
    "supporting": ["ev-container_logs_tail", "ev-pod_states", "ev-target_events", "ev-rollout_history"],
