    "root_cause_class": "new_version_broken",
    "summary": "The current revision introduced probe failures, as prior revisions were healthy.",
    "supporting": ["ev-rollout_history", "ev-pod_states", "ev-target_events"],
    "contradicting": [],
    "missing": [],
    "status": "supported"
  }
],
"proposal": {
  "capability": "deployment.set-probes",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "edge",
    "name": "api-gateway",
    "uid": "uid-deployment-api-gateway"
  },
  "params": {
    "container": "app",
    "liveness": {
      "initialDelaySeconds": 20,
      "timeoutSeconds": 5
    },
    "readiness": {
      "initialDelaySeconds": 5,
      "timeoutSeconds": 3
    }
  },
  "expected_effect": "The liveness probe will wait longer before timing out, allowing the application to start and respond to probes before being killed.",
  "rationale": "The pod was killed during startup (killed_during_startup: true) with liveness probe failures. The current timeoutSeconds (1) is too short for the application to respond. Increasing these values aligns with the observed startup duration (1m2s) and prevents premature termination.",
  "cited_evidence_ids": ["ev-container_logs_tail", "ev-pod_states", "ev-target_events", "ev-rollout_history"],
  "cited_predicates": ["killed_during_startup", "probe_kills", "rollout_recent"]
} }
